SELECT EXISTS (
    SELECT 1
    FROM sr_dag_node_attempt a
    JOIN sr_dag_node_instance n ON n.id = a.node_instance_id
    JOIN sr_dag_instance d ON d.id = a.dag_instance_id
    JOIN sr_worker w ON CAST(w.id AS varchar) = a.worker_id
    WHERE a.id = CAST(#{context.attemptId} AS bigint)
      AND a.dag_instance_id = #{context.dagInstanceId}
      AND a.node_instance_id = #{context.nodeInstanceId}
      AND a.attempt_no = #{context.attemptNo}
      AND a.request_id = #{context.requestId}
      AND a.request_checksum = #{context.requestChecksum}
      AND a.dispatch_generation = #{context.dispatchGeneration}
      AND a.dispatch_token = #{context.dispatchToken}
      AND a.attempt_lease_version = #{context.attemptLeaseVersion}
      AND a.worker_id = #{context.workerId}
      AND a.worker_epoch = #{context.workerEpoch}
      AND n.dag_instance_id = #{context.dagInstanceId}
      AND n.node_id = #{context.nodeCode}
      AND n.current_attempt_id = a.id
      AND n.current_attempt_no = a.attempt_no
      AND n.dispatch_generation = a.dispatch_generation
      AND n.dispatch_token = a.dispatch_token
      AND d.status = 10
      AND n.status = 40
      AND a.status IN (20, 30)
      AND a.capacity_released_at IS NULL
      AND CAST(w.worker_epoch AS varchar) = #{context.workerEpoch}
)

